import http from './http'

export function updateUserLabel(userId, payload) {
  return http.put(`/admin/users/${userId}/label`, payload)
}

import http from './http'

export function login(payload) {
  return http.post('/auth/login', payload)
}

export function register(payload) {
  return http.post('/auth/register', payload)
}

export function me() {
  return http.get('/auth/me')
}

import axios from 'axios'

const http = axios.create({
  baseURL: process.env.VUE_APP_API_BASE || 'http://localhost:8090/api',
  timeout: 15000
})

http.interceptors.request.use(config => {
  const token = localStorage.getItem('token')
  if (token) {
    config.headers.Authorization = `Bearer ${token}`
  }
  return config
})

export default http

import http from './http'

export function searchUsers(payload) {
  return http.post('/users/search', payload)
}

export function getUserDetail(userId) {
  return http.get(`/users/${userId}`)
}

export function getUserWordCloud(userId) {
  return http.get(`/users/${userId}/wordcloud`)
}

export function getUserActiveHours(userId) {
  return http.get(`/users/${userId}/active-hours`)
}

import { createRouter, createWebHistory } from 'vue-router'
import Login from '../views/Login.vue'
import Register from '../views/Register.vue'
import UserList from '../views/UserList.vue'
import UserDetail from '../views/UserDetail.vue'
import AdminUsers from '../views/AdminUsers.vue'
import CurrentUser from '../views/CurrentUser.vue'

const routes = [
  { path: '/', redirect: '/login' },
  { path: '/login', component: Login },
  { path: '/register', component: Register },
  { path: '/users', component: UserList },
  { path: '/users/:id', component: UserDetail, props: true },
  { path: '/admin/users', component: AdminUsers },
  { path: '/me', component: CurrentUser }
]

const router = createRouter({
  history: createWebHistory(),
  routes
})

router.beforeEach((to, from, next) => {
  const token = localStorage.getItem('token')
  const publicPaths = ['/login', '/register']
  if (!token && !publicPaths.includes(to.path)) {
    next('/login')
    return
  }
  if (token && publicPaths.includes(to.path)) {
    next('/users')
    return
  }
  next()
})

export default router

